from pathlib import Path
p = Path('/home/ubuntu/qgram/client/src/pages/Home.tsx')
s = p.read_text()

# Add state for real settings/reels controls.
s = s.replace('''function SecondaryPage({ tab, onTab, displayName, isAuthenticated }: { tab: Tab; onTab: (tab: Tab) => void; displayName: string; isAuthenticated: boolean }) {\n  const [userSearch, setUserSearch] = useState("");''', '''function SecondaryPage({ tab, onTab, displayName, isAuthenticated }: { tab: Tab; onTab: (tab: Tab) => void; displayName: string; isAuthenticated: boolean }) {\n  const [userSearch, setUserSearch] = useState("");\n  const [settingsSection, setSettingsSection] = useState("profile");\n  const [reelsMuted, setReelsMuted] = useState(true);\n  const [privateAccount, setPrivateAccount] = useState(false);\n  const [allowComments, setAllowComments] = useState(true);''')

# Replace Reels grid with a vertical, snap-scrolling viewer.
old_reels = '''      {tab === "reels" && <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{videos.map((video) => <button type="button" key={video.title} onClick={() => toast("پخش ویدیو در نسخه‌ی بعدی کامل‌تر می‌شود.")} className="group relative aspect-[.72] overflow-hidden rounded-[22px] bg-[#1d2746] text-right"><img src={`https://images.unsplash.com/${video.image}?auto=format&fit=crop&w=600&q=85`} alt={video.title} className="h-full w-full object-cover opacity-85 transition duration-300 group-hover:scale-105" /><div className="absolute inset-0 bg-gradient-to-t from-[#11182f]/90 via-transparent to-transparent" /><div className="absolute inset-x-3 bottom-3 text-white"><PlaySquare size={18} className="mb-2" /><p className="text-xs font-black leading-5">{video.title}</p><p className="mt-1 text-[10px] text-white/65">@{video.user}</p></div></button>)}</div>}'''
new_reels = '''      {tab === "reels" && <section className="relative mx-auto max-w-[430px]"><div className="h-[min(72vh,680px)] snap-y snap-mandatory space-y-4 overflow-y-auto rounded-[18px] bg-[#080b14] p-2 shadow-[0_20px_60px_rgba(8,11,20,.18)]">{videos.concat(videos.slice(0, 2)).map((video, index) => <article key={`${video.title}-${index}`} className="relative h-[min(68vh,640px)] snap-start overflow-hidden rounded-[14px] bg-[#151a29]"><img src={`https://images.unsplash.com/${video.image}?auto=format&fit=crop&w=1000&q=90`} alt={video.title} className="h-full w-full object-cover" /><div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-black/10" /><button type="button" onClick={() => setReelsMuted((value) => !value)} className="absolute left-4 top-4 grid h-10 w-10 place-items-center rounded-full bg-black/45 text-white text-xs font-black">{reelsMuted ? "صدا" : "بی‌صدا"}</button><div className="absolute bottom-5 right-5 left-16 text-white"><div className="mb-3 flex items-center gap-3"><Avatar src={avatarUrl(video.image)} alt={video.user} size="md" ring /><b className="text-sm">@{video.user}</b><button type="button" onClick={() => toast(`دنبال‌کردن ${video.user}`)} className="rounded-lg border border-white/50 px-3 py-1 text-[10px] font-bold">دنبال کن</button></div><p className="text-sm font-bold leading-7">{video.title} · لحظه‌های کوتاه برای دیدن و به اشتراک گذاشتن</p><div className="mt-4 flex items-center gap-4 text-xs font-bold"><button type="button" onClick={() => toast("ریلز پسندیده شد.")}>♡ ۲۴۸K</button><button type="button" onClick={() => toast("دیدگاه‌ها باز شد.")}>◯ ۸۶۱</button><button type="button" onClick={() => toast("لینک ریلز کپی شد.")}>↗ اشتراک</button><button type="button" onClick={() => toast("ریلز ذخیره شد.")}>☆ ذخیره</button></div></div></article>)}</div><p className="mt-3 text-center text-[11px] text-[#9ba1b1]">برای دیدن ویدیوی بعدی اسکرول کن · صدا: {reelsMuted ? "خاموش" : "روشن"}</p></section>}'''
if old_reels not in s:
    raise SystemExit('old reels block not found')
s = s.replace(old_reels, new_reels)

# Replace messages list with split inbox.
old_messages = '''      {tab === "messages" && <section className="overflow-hidden rounded-[26px] border border-[#eef0f6] bg-white">{messages.map((message, index) => <button type="button" key={message.name} onClick={() => toast(`گفت‌وگو با ${message.name} باز شد.`)} className={`flex w-full items-center gap-3 p-4 text-right transition hover:bg-[#fafbff] ${index ? "border-t border-[#f0f1f6]" : ""}`}><Avatar src={avatarUrl(message.image)} alt={message.name} size="md" ring /><span className="min-w-0 flex-1"><b className="block text-sm font-black">{message.name}</b><span className="mt-1 block truncate text-xs text-[#8e95a8]">{message.text}</span></span><span className="text-[10px] text-[#a6acba]">{message.time}</span></button>)}</section>}'''
new_messages = '''      {tab === "messages" && <section className="grid min-h-[520px] overflow-hidden rounded-[16px] border border-[#e8e8e8] bg-white md:grid-cols-[240px_1fr]" dir="ltr"><div className="border-b border-[#eeeeee] md:border-b-0 md:border-r"><div className="flex items-center justify-between border-b border-[#eeeeee] p-4"><b className="text-sm" dir="rtl">پیام‌ها</b><button type="button" onClick={() => toast("گفت‌وگوی جدید ساخته می‌شود.")} className="text-lg">＋</button></div><div className="p-3"><input placeholder="جست‌وجو" className="h-9 w-full rounded-lg bg-[#f5f5f5] px-3 text-xs outline-none" dir="rtl" /></div>{messages.map((message) => <button type="button" key={message.name} onClick={() => toast(`گفت‌وگو با ${message.name} باز شد.`)} className="flex w-full items-center gap-2 px-3 py-3 text-left hover:bg-[#fafafa]"><Avatar src={avatarUrl(message.image)} alt={message.name} size="sm" ring /><span className="min-w-0"><b className="block truncate text-xs">{message.name}</b><span className="block truncate text-[10px] text-[#8e95a8]">{message.text}</span></span></button>)}</div><div className="hidden flex-col items-center justify-center gap-3 p-8 text-center md:flex" dir="rtl"><div className="grid h-16 w-16 place-items-center rounded-full border border-[#222]"><Send size={26} /></div><h2 className="text-xl font-bold">پیام‌های شما</h2><p className="text-xs text-[#8e95a8]">یک گفت‌وگو را انتخاب کن یا پیام جدید بفرست.</p><button type="button" onClick={() => toast("گفت‌وگوی جدید ساخته می‌شود.")} className="rounded-lg bg-[#111] px-4 py-2 text-xs font-bold text-white">ارسال پیام</button></div></section>}'''
if old_messages not in s:
    raise SystemExit('old messages block not found')
s = s.replace(old_messages, new_messages)

# Replace settings placeholder with real two-pane controls.
# Replace the placeholder settings panel by matching the current source block robustly.
import re
new_settings = """      {tab === \"settings\" && <section className=\"grid overflow-hidden rounded-[16px] border border-[#e8e8e8] bg-white md:grid-cols-[230px_1fr]\" dir=\"ltr\"><nav className=\"border-b border-[#eeeeee] p-2 md:border-b-0 md:border-r\">{[{ key: \"profile\", title: \"ویرایش پروفایل\", icon: <UserRound size={17} /> }, { key: \"notifications\", title: \"اعلان‌ها\", icon: <Bell size={17} /> }, { key: \"privacy\", title: \"حریم خصوصی\", icon: <UsersRound size={17} /> }, { key: \"comments\", title: \"کامنت‌ها\", icon: <MessageCircle size={17} /> }, { key: \"language\", title: \"زبان\", icon: <Sparkles size={17} /> }, { key: \"account\", title: \"نوع حساب و ابزارها\", icon: <Settings size={17} /> }].map((item) => <button type=\"button\" key={item.key} onClick={() => setSettingsSection(item.key)} className={`flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left text-xs font-bold ${settingsSection === item.key ? \"bg-[#f1f1f1] text-[#111]\" : \"text-[#777] hover:bg-[#fafafa]\"}`}><span>{item.icon}</span><span dir=\"rtl\">{item.title}</span></button>)}</nav><div className=\"min-h-[430px] p-6\" dir=\"rtl\">{settingsSection === \"profile\" && <div><h2 className=\"text-xl font-bold\">ویرایش پروفایل</h2><p className=\"mt-2 text-xs leading-6 text-[#888]\">اطلاعات عمومی پروفایل و معرفی کوتاه خودت را مدیریت کن.</p><div className=\"mt-6 space-y-4\"><label className=\"block text-xs font-bold\">نام کاربری<input defaultValue=\"mina.qgram\" className=\"mt-2 h-11 w-full rounded-lg border border-[#ddd] px-3 text-sm outline-none\" /></label><label className=\"block text-xs font-bold\">Bio<textarea defaultValue=\"عاشق قاب‌های ساده، سفرهای کوتاه و آدم‌های خوش‌قلب.\" className=\"mt-2 min-h-24 w-full rounded-lg border border-[#ddd] p-3 text-sm outline-none\" /></label><button type=\"button\" onClick={() => toast(\"پروفایل ذخیره شد.\")} className=\"rounded-lg bg-[#111] px-5 py-3 text-xs font-bold text-white\">ذخیره تغییرات</button></div></div>}{settingsSection === \"privacy\" && <div><h2 className=\"text-xl font-bold\">حریم خصوصی حساب</h2><p className=\"mt-2 text-xs leading-6 text-[#888]\">وقتی حساب خصوصی باشد، فقط دنبال‌کننده‌های تأییدشده پست‌ها را می‌بینند.</p><div className=\"mt-7 flex items-center justify-between border-b border-[#eee] py-5\"><div><b className=\"block text-sm\">حساب خصوصی</b><small className=\"mt-1 block text-xs text-[#999]\">کنترل کن چه کسی محتوای تو را ببیند.</small></div><button type=\"button\" role=\"switch\" aria-checked={privateAccount} onClick={() => setPrivateAccount((value) => !value)} className={`h-7 w-12 rounded-full p-1 transition ${privateAccount ? \"bg-[#111]\" : \"bg-[#ddd]\"}`}><span className={`block h-5 w-5 rounded-full bg-white transition ${privateAccount ? \"translate-x-5\" : \"translate-x-0\"}`} /></button></div></div>}{settingsSection === \"comments\" && <div><h2 className=\"text-xl font-bold\">کامنت‌ها</h2><p className=\"mt-2 text-xs leading-6 text-[#888]\">انتخاب کن چه کسانی بتوانند روی پست‌هایت نظر بدهند.</p><div className=\"mt-7 flex items-center justify-between border-b border-[#eee] py-5\"><b className=\"text-sm\">اجازه‌ی کامنت</b><button type=\"button\" role=\"switch\" aria-checked={allowComments} onClick={() => setAllowComments((value) => !value)} className={`h-7 w-12 rounded-full p-1 transition ${allowComments ? \"bg-[#111]\" : \"bg-[#ddd]\"}`}><span className={`block h-5 w-5 rounded-full bg-white transition ${allowComments ? \"translate-x-5\" : \"translate-x-0\"}`} /></button></div></div>}{settingsSection === \"notifications\" && <div><h2 className=\"text-xl font-bold\">اعلان‌ها</h2><p className=\"mt-2 text-xs leading-6 text-[#888]\">اعلان‌های فالو، لایک، کامنت و پیام را مدیریت کن.</p>{[\"لایک و کامنت\", \"دنبال‌کننده‌های جدید\", \"پیام‌ها\"].map((label) => <div key={label} className=\"flex items-center justify-between border-b border-[#eee] py-5\"><b className=\"text-sm\">{label}</b><span className=\"rounded-full bg-[#e9f8e9] px-3 py-1 text-[10px] font-bold text-[#2f8c3a]\">فعال</span></div>)}</div>}{settingsSection === \"language\" && <div><h2 className=\"text-xl font-bold\">زبان برنامه</h2><p className=\"mt-2 text-xs leading-6 text-[#888]\">زبان نمایش کیو گرام را انتخاب کن.</p><div className=\"mt-6 space-y-2\">{[\"فارسی\", \"English\", \"العربية\"].map((label, index) => <button type=\"button\" key={label} onClick={() => toast(`زبان ${label} انتخاب شد.`)} className=\"flex w-full items-center justify-between rounded-lg border border-[#eee] px-4 py-3 text-sm\"><span>{label}</span>{index === 0 && <Check size={16} />}</button>)}</div></div>}{settingsSection === \"account\" && <div><h2 className=\"text-xl font-bold\">نوع حساب و ابزارها</h2><p className=\"mt-2 text-xs leading-6 text-[#888]\">حساب حرفه‌ای، Creator tools و قابلیت‌های آینده را مدیریت کن.</p><button type=\"button\" onClick={() => toast(\"فرآیند تبدیل به حساب حرفه‌ای شروع شد.\")} className=\"mt-7 flex w-full items-center justify-between rounded-lg border border-[#eee] px-4 py-4 text-sm\"><span>تبدیل به حساب حرفه‌ای</span><ChevronLeft size={16} /></button></div>}</div></section>}"""
pattern = r'      \{tab === "settings" && <section[\s\S]*?</section>\}'
if not re.search(pattern, s):
    raise SystemExit("settings regex target not found")
s = re.sub(pattern, new_settings, s, count=1)


# Make the desktop shell visually closer to Instagram: sidebar left, lighter background, flatter cards.
s = s.replace('''<div dir="rtl" className="min-h-screen bg-[#f8f9fc] text-[#202844]">''', '''<div dir="rtl" className="min-h-screen bg-white text-[#202844]">''')
s = s.replace('''<div className="mx-auto grid max-w-[1420px] grid-cols-1 gap-7 px-4 py-7 lg:grid-cols-[230px_minmax(0,1fr)_280px] lg:px-10">\n        <aside className="hidden lg:block">''', '''<div dir="ltr" className="mx-auto grid max-w-[1420px] grid-cols-1 gap-7 px-4 py-7 lg:grid-cols-[230px_minmax(0,1fr)_280px] lg:px-10">\n        <aside dir="rtl" className="hidden lg:block">''')
s = s.replace('''        <main className="mx-auto w-full max-w-[700px] min-w-0">''', '''        <main dir="rtl" className="mx-auto w-full max-w-[700px] min-w-0">''')
s = s.replace('''        <aside className="hidden lg:block"><div className="sticky top-[104px]''', '''        <aside dir="rtl" className="hidden lg:block"><div className="sticky top-[104px]''')
# Lighter, flatter cards for the feed and right rail.
s = s.replace('rounded-[26px] border border-[#eef0f6] bg-white shadow-[0_12px_40px_rgba(35,49,92,.04)]', 'rounded-[12px] border border-[#eeeeee] bg-white')
s = s.replace('rounded-[28px] bg-[#263b82] p-6 text-white shadow-[0_20px_50px_rgba(38,59,130,.2)]', 'rounded-[12px] bg-[#111] p-6 text-white')

p.write_text(s)
